// Package keymap loads the canonical cross-platform key table
// (shared/keymap/hid-keymap.json, generated by Tools/gen_keymap.py from
// Chromium's dom_code_data.inc) and answers lookups between the wire value
// used by Edgehop and Reach, DOM code names, macOS virtual key codes and
// Windows Set-1 scan codes.
//
// Wire values are USB HID usages: page 0x07 keys use the usage itself, page
// 0x0C (consumer / media) keys use 0x1000+usage and page 0x01 keys 0x2000+usage,
// so play/pause is 0x10CD (docs/edgehop-protocol.md §5).
package keymap

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"sync"
)

//go:embed hid-keymap.json
var embedded []byte

// Key is one row of the table.
type Key struct {
	// Usage is the HID usage: the 16-bit usage for page 0x07, otherwise
	// page<<16 | usage.
	Usage int `json:"usage"`
	// Page is the HID usage page (0x01, 0x07 or 0x0C).
	Page int `json:"page"`
	// Wire is the value carried in Edgehop key frames and used by Reach key names.
	Wire int `json:"wire"`
	// Mac is the macOS virtual key code (kVK_*), -1 when the key has none.
	Mac int `json:"mac"`
	// WinScan is the Windows Set-1 scan code byte, 0 when the key has none.
	WinScan int `json:"winScan"`
	// Evdev is the Linux evdev key code.
	Evdev int `json:"evdev"`
	// WinExt is true when the scan code carries the E0 prefix (KEYEVENTF_EXTENDEDKEY).
	WinExt bool `json:"winExt"`
	// Dom is the DOM KeyboardEvent.code name ("KeyA", "ArrowLeft", "MediaPlayPause"), "" when none.
	Dom string `json:"dom"`
	// Ident is Chromium's identifier for the key ("US_A", "ARROW_LEFT").
	Ident string `json:"ident"`
}

// Map is an indexed key table.
type Map struct {
	keys    []Key
	byWire  map[int]Key
	byDom   map[string]Key
	byMac   map[int]Key
	byWin   map[winKey]Key
	byEvdev map[int]Key
}

type winKey struct {
	scan int
	ext  bool
}

type file struct {
	Keys []Key `json:"keys"`
}

// Parse builds a Map from the JSON document format of hid-keymap.json.
func Parse(data []byte) (*Map, error) {
	var f file
	if err := json.Unmarshal(data, &f); err != nil {
		return nil, fmt.Errorf("keymap: parse: %w", err)
	}
	if len(f.Keys) == 0 {
		return nil, fmt.Errorf("keymap: no keys in table")
	}
	m := &Map{
		keys:    f.Keys,
		byWire:  make(map[int]Key, len(f.Keys)),
		byDom:   make(map[string]Key, len(f.Keys)),
		byMac:   make(map[int]Key, len(f.Keys)),
		byWin:   make(map[winKey]Key, len(f.Keys)),
		byEvdev: make(map[int]Key, len(f.Keys)),
	}
	for _, k := range f.Keys {
		if _, dup := m.byWire[k.Wire]; dup {
			return nil, fmt.Errorf("keymap: duplicate wire value %#x", k.Wire)
		}
		m.byWire[k.Wire] = k
		if k.Dom != "" {
			m.byDom[k.Dom] = k
		}
		if k.Mac >= 0 {
			if _, dup := m.byMac[k.Mac]; !dup {
				m.byMac[k.Mac] = k
			}
		}
		if k.WinScan > 0 {
			wk := winKey{k.WinScan, k.WinExt}
			if _, dup := m.byWin[wk]; !dup {
				m.byWin[wk] = k
			}
		}
		if k.Evdev > 0 {
			if _, dup := m.byEvdev[k.Evdev]; !dup {
				m.byEvdev[k.Evdev] = k
			}
		}
	}
	return m, nil
}

var (
	defaultOnce sync.Once
	defaultMap  *Map
	defaultErr  error
)

// Default returns the embedded table, parsed once. The embedded file is
// validated by the package tests, so a parse failure here is a build error
// and Default panics rather than returning nil.
func Default() *Map {
	defaultOnce.Do(func() {
		defaultMap, defaultErr = Parse(embedded)
	})
	if defaultErr != nil {
		panic(defaultErr)
	}
	return defaultMap
}

// Keys returns every row in file order. The slice must not be modified.
func (m *Map) Keys() []Key { return m.keys }

// ByWire looks a key up by its wire value.
func (m *Map) ByWire(wire int) (Key, bool) {
	k, ok := m.byWire[wire]
	return k, ok
}

// ByDom looks a key up by its DOM code name ("KeyA", "ArrowLeft").
func (m *Map) ByDom(dom string) (Key, bool) {
	k, ok := m.byDom[dom]
	return k, ok
}

// ByMac looks a key up by its macOS virtual key code.
func (m *Map) ByMac(code int) (Key, bool) {
	k, ok := m.byMac[code]
	return k, ok
}

// ByWinScan looks a key up by its Windows Set-1 scan code and E0-prefix flag.
// Scan code 0 never matches.
func (m *Map) ByWinScan(scan int, ext bool) (Key, bool) {
	k, ok := m.byWin[winKey{scan, ext}]
	return k, ok
}

// ByEvdev looks a key up by its Linux evdev key code.
func (m *Map) ByEvdev(code int) (Key, bool) {
	k, ok := m.byEvdev[code]
	return k, ok
}

// Modifier usages (page 0x07) and the bits they occupy in the wire modifier byte.
const (
	ModLeftControl  = 0xE0
	ModLeftShift    = 0xE1
	ModLeftAlt      = 0xE2
	ModLeftGUI      = 0xE3
	ModRightControl = 0xE4
	ModRightShift   = 0xE5
	ModRightAlt     = 0xE6
	ModRightGUI     = 0xE7
)

// IsModifier reports whether wire is one of the eight modifier usages 0xE0..0xE7.
func IsModifier(wire int) bool {
	return wire >= ModLeftControl && wire <= ModRightGUI
}

// ModifierBit returns the bit a modifier usage occupies in the wire modifier
// byte (bit0 LCtrl … bit7 RGUI), ok=false for any other wire value.
func ModifierBit(wire int) (bit uint8, ok bool) {
	if !IsModifier(wire) {
		return 0, false
	}
	return 1 << uint(wire-ModLeftControl), true
}
